android.extraProguardRules:
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
-keepclasseswithmembers class * { native <methods>; }
-keep interface com.facebook.react.turbomodule.core.interfaces.TurboModule { *; }
-keep class * extends com.facebook.react.bridge.NativeModule { *; }
-keep class * extends com.facebook.react.bridge.JavaScriptModule { *; }
-keepclassmembers class * extends com.facebook.react.bridge.ReactContextBaseJavaModule { @com.facebook.react.bridge.ReactMethod *; }
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn javax.annotation.**
